import math

solutions = []

# Iterate through small values of a, b, c (up to 10)
for a in range(1, 11):
    for b in range(1, 11):
        for c in range(1, 11):
            # The equation is 2^a + 3^b + 1 = 6^c
            LHS = 2**a + 3**b + 1
            RHS = 6**c

            if LHS == RHS:
                # Found a solution (a, b, c)
                # Calculate the near numbers (B, T, S)
                B = 2**a + 1
                T = 3**b + 1
                S = 6**c + 1

                solutions.append({
                    'a': a, 'b': b, 'c': c,
                    'B': B, 'T': T, 'S': S
                })

if solutions:
    print("Found solutions (a, b, c) and corresponding near numbers (B, T, S):")
    for sol in solutions:
        print(f"Triple (a, b, c): ({sol['a']}, {sol['b']}, {sol['c']})")
        print(f"Near Numbers (B, T, S): ({sol['B']}, {sol['T']}, {sol['S']})")
        print("-" * 20)
else:
    print("No solutions found for a, b, c up to 10.")
